INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p126788-econ305', 'stk-user2166', 'ECON 305', 'info', '{"desc": "الأيكون انا اخذتها مع رمادي\n\nبس مايدرسها الحين\n\nالترم الجاي يمكن ينزلها\n\nخذها عنده\n\nوغثه با الاسئله با الكلاس لوها غلط\n\nويجيك القريد\n\nوعلى فكره الميد تيرم والفاينل حقه يعطيك عشرة اسئله قبل الاختبار با اسبوعين تحل خمسه منها انت تختارها وقت الاختبار ولا فيه اسهل منها\n\nوالسؤال اللي شايف انه سهل وتبي تحله\n\nالاجابه حاول انها تكون حوول كلامه\n\nيعني رمادي اوبنين\n\nيعني لو مثلا قال لك عميد جامعة الملك فهد كوفي عنان\n\nالجواب اكتب كوفي عنان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-305/52745/5", "user": "user2166", "ts": 1162557494000, "tid": 52745, "pn": 5}}', 1162557494000, 1794837143, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p937599-econ305', 'stk-sgrww17', 'ECON 305', 'info', '{"desc": "ايكون 305 - ايكون 306 - فاينص 302 - mgt301 -engl214\n\nاوما ،،، احسسسها صعبة و المواد غثيثة شوي\n\nايكون 305 حلوووة مع اشرف عيد 306 لسى ما اخذتها فايننس لسسى بس يقولوا يبغى لها شغل حتى اـ 306 يبي لها شوية شغغغل\n\nاما الانقلش فهذه مع جوش بيلام و لا تحس انك منزل كورس اصلا ، اساسا المادة ثقيلة و فيها شغل كثير\n\nام جي تي عندي الحين مع دكتور عوكل الجزائري ، المادة جدا طويلة و يبي لها مذاكرة اول باول\n\nاذا عندك سؤال محدد حياك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/305-306-302/115567/4", "user": "sgrww17", "ts": 1322326504000, "tid": 115567, "pn": 4}}', 1322326504000, 1794837143, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p938490-econ305', 'stk-f.a.b', 'ECON 305', 'info', '{"desc": "ايكون 305 < اشرف عيد وصعوبتها متوسطه ميزتها تنفهم احسن من 101 و 202\nايكون 306 < لاتاخذها مع غير الدكتور زهير يماني واعتبر نفسك مو منزل ماده اهتم بالحضور واقرا السلايدات قرايه سريعه\nفاينانس 302 مو صعبه\nانقلش 214 < عاد انقلش اكيد فيها غثا كتابة وشغل كثير وناسي اسماء الدكاتره للاسف\nمنجمنت 301 < كثرة قرق يعني احسبلها 4 ايام مذاكره قبل الامتحان مو لازم دايم تتابعها يعني\nاشوف جدولك متوسط مو صعب بس نظم وقتك\nتحياتي لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/305-306-302/115567/5", "user": "F.A.B", "ts": 1322427997000, "tid": 115567, "pn": 5}}', 1322427997000, 1794837143, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
